  // د موقعیت او محاسبې د تنظیماتو له بدلېدو سره د لمانځه وختونه اتومات تازه کېږي.
  useEffect(() => {
    if (Number.isFinite(settings.latitude) && Number.isFinite(settings.longitude)) {
      calculatePrayerTimes(settings.latitude, settings.longitude);
    }
  }, [settings.latitude, settings.longitude, settings.calculationMethod, settings.madhab,
      settings.prayerAdjustments?.fajr, settings.prayerAdjustments?.sunrise,
      settings.prayerAdjustments?.dhuhr, settings.prayerAdjustments?.asr,
      settings.prayerAdjustments?.maghrib, settings.prayerAdjustments?.isha]);

  // د نېټې بدلېدو/نیمې شپې په ګډون وختونه تازه ساتي.
  useEffect(() => {
    const timer = setInterval(() => {
      if (Number.isFinite(settings.latitude) && Number.isFinite(settings.longitude)) {
        calculatePrayerTimes(settings.latitude, settings.longitude);
      }
    }, 60 * 1000);
    return () => clearInterval(timer);
  }, [settings.latitude, settings.longitude, settings.calculationMethod, settings.madhab]);

  // ==================================================
  // 21 - د لمانځه محاسبه
  // ==================================================

  function getCalculationParams() {
    switch (settings.calculationMethod) {
      case 'UmmAlQura':
        return CalculationMethod.UmmAlQura();

      case 'MuslimWorldLeague':
        return CalculationMethod.MuslimWorldLeague();

      case 'Egyptian':
        return CalculationMethod.Egyptian();

      case 'NorthAmerica':
        return CalculationMethod.NorthAmerica();

      default:
        return CalculationMethod.Karachi();
    }
  }

  async function calculatePrayerTimes(latitude, longitude) {
    try {
      const coordinates = new Coordinates(
        latitude,
        longitude
      );

      const params = getCalculationParams();

      params.madhab =
        settings.madhab === 'Shafi'
          ? Madhab.Shafi
          : Madhab.Hanafi;

      const date = new Date();

      const times = new PrayerTimes(
        coordinates,
        date,
        params
      );

      const adjustments = settings.prayerAdjustments || {};

      function adjustTime(value, minutes) {
        const result = new Date(value);
        result.setMinutes(
          result.getMinutes() + (minutes || 0)
        );
        return result;
      }

      const result = {
        fajr: adjustTime(times.fajr, adjustments.fajr),
        sunrise: adjustTime(times.sunrise, adjustments.sunrise),
        dhuhr: adjustTime(times.dhuhr, adjustments.dhuhr),
        asr: adjustTime(times.asr, adjustments.asr),
        maghrib: adjustTime(times.maghrib, adjustments.maghrib),
        isha: adjustTime(times.isha, adjustments.isha)
      };

      setPrayerTimes(result);
      setPrayerDate(new Date());

      return result;

    } catch (error) {
      Alert.alert('ستونزه', 'د لمانځه وختونه محاسبه نه شول.');
      return null;
    }
  }

  // ==================================================
  // 22 - د موقعیت ترلاسه کول
  // ==================================================

  async function getPrayerLocation() {
    try {
      setLocationLoading(true);

      const permission =
        await Location.requestForegroundPermissionsAsync();

      if (permission.status !== 'granted') {
        Alert.alert(
          'اجازه اړینه ده',
          'د لمانځه د وختونو لپاره د موقعیت اجازه ورکړئ.'
        );
        return;
      }

      const location =
        await Location.getCurrentPositionAsync({
          accuracy: Location.Accuracy.Balanced
        });

      const latitude = location.coords.latitude;
      const longitude = location.coords.longitude;

      const address = await Location.reverseGeocodeAsync({
        latitude,
        longitude
      });

      const cityName =
        address?.[0]?.city ||
        address?.[0]?.district ||
        address?.[0]?.region ||
        '';

      await updateSettings({
        latitude,
        longitude,
        city: cityName
      });

      await calculatePrayerTimes(
        latitude,
        longitude
      );

    } catch (error) {
      Alert.alert('ستونزه', 'موقعیت ترلاسه نه شو.');
    } finally {
      setLocationLoading(false);
    }
  }

  async function refreshPrayerTimes() {
    if (
      settings.latitude !== null &&
      settings.longitude !== null
    ) {
      await calculatePrayerTimes(
        settings.latitude,
        settings.longitude
      );
    } else {
      await getPrayerLocation();
    }
  }

