  async function deleteOldChapter(chapterId) {
    if (!selectedItem) return;

    const key = getBookKey();

    const updatedBooks = (books[key] || []).map(book =>
      book.id === selectedItem.id
        ? {
            ...book,
            chapters: (book.chapters || []).filter(
              chapter => chapter.id !== chapterId
            )
          }
        : book
    );

    await saveBooks({
      ...books,
      [key]: updatedBooks
    });

    setSelectedItem(
      updatedBooks.find(
        book => book.id === selectedItem.id
      )
    );
  }

  // ==================================================
  // 30 - د لټون سیستم
  // ==================================================

  function getSearchResults() {
    const query = searchText.trim().toLocaleLowerCase();
    if (!query) return [];
    const matches = [];
    const has = value => String(value || '').toLocaleLowerCase().includes(query);

    globalItems.forEach(item => {
      if (has(`${item.title} ${item.description} ${item.text} ${item.scholar} ${item.section} ${item.folder}`)) {
        matches.push({ ...item, _resultType: 'lesson' });
      }
    });
    notes.forEach(item => {
      if (has(`${item.title} ${item.text}`)) matches.push({ ...item, _resultType: 'note', _resultLabel: 'شخصي نوټ' });
    });
    adhkar.forEach(item => {
      if (has(`${item.title} ${item.text} ${item.description} ${item.category}`)) matches.push({ ...item, _resultType: 'dhikr', _resultLabel: 'ذکر' });
    });
    Object.entries(books || {}).forEach(([bookGroup, groupBooks]) => {
      (Array.isArray(groupBooks) ? groupBooks : []).forEach(book => {
        if (has(`${book.title} ${book.name} ${book.description} ${bookGroup}`)) {
          matches.push({ id: book.id || `book-${book.title}`, title: book.title || book.name || 'کتاب', description: book.description || '', _resultType: 'book', _resultLabel: 'کتاب', _book: book, _bookGroup: bookGroup });
        }
        (book.chapters || []).forEach(chapter => {
          if (has(`${chapter.title} ${chapter.name} ${book.title}`)) {
            matches.push({ id: chapter.id, title: chapter.title || chapter.name || 'څپرکی', description: book.title || '', _resultType: 'book', _resultLabel: 'د کتاب څپرکی', _book: book, _bookGroup: bookGroup });
          }
          (chapter.lessons || []).forEach(lesson => {
            if (has(`${lesson.title} ${lesson.name} ${book.title} ${chapter.title}`)) {
              matches.push({ id: lesson.id, title: lesson.title || lesson.name || 'درس', description: book.title || '', _resultType: 'book', _resultLabel: 'د کتاب درس', _book: book, _bookGroup: bookGroup });
            }
          });
        });
      });
    });
    return matches.slice(0, 150);
  }

  function openSearchResult(item) {
    if (item._resultType === 'note') { openNote(item); return; }
    if (item._resultType === 'dhikr') { setSelectedDhikr(item); setScreen('dhikrDetails'); return; }
    if (item._resultType === 'book') {
      const [scholar, section] = String(item._bookGroup || '').split('|');
      setSelectedScholar(scholar || '');
      setSelectedSection(section || '');
      setSelectedItem(item._book || item);
      setScreen('oldBook');
      return;
    }
    openItem(item);
  }

  function openItem(item) {
    setSelectedItem(item);
    setScreen('itemDetails');
  }

