                <TouchableOpacity style={styles.designStepButton} onPress={() => updateHomeDesign({ titleSize: Math.min(24, getHomeFolderDesign(designFolderKey).titleSize + 1) }, designFolderKey)}><Text style={styles.designStepText}>{t("+ غټ")}</Text></TouchableOpacity>
